	assert.equal(composeChildPrompt({ family: "deepseek", rolePrompt: on.text, common: true }).text, on.text);
	assert.doesNotMatch(composeChildPrompt({ family: "deepseek", rolePrompt: "Stay a worker." }).text, /Think concisely/);
	assert.equal(composeChildPrompt({ family: "pi-default", rolePrompt: "Stay a worker.", common: true }).text, "Stay a worker.");
});

