import assert from "node:assert/strict";
import { existsSync } from "node:fs";
import { join } from "node:path";
import test from "node:test";
import { HARNESS_NAMES } from "./defaults.ts";
import { commonBody, defaultSourcesRoot, loadHarnessSources, overlayBody, renderOverlay } from "./prompt.ts";

test("every parent harness name has a SOURCE profile and listed overlay files exist", () => {
	const loaded = loadHarnessSources();
	assert.ok(loaded.length > 0);
	const claimed = new Set<string>();
	for (const source of loaded) {
		assert.equal(source.family, source.dir.split("/").at(-1));
		assert.match(source.ref.rev, /^[0-9a-f]{40}$/);
		if (source.shared) {
			assert.equal(existsSync(join(source.dir, source.shared)), true, source.shared);
		}
		for (const [name, profile] of Object.entries(source.profiles)) {
			assert.equal(claimed.has(name), false, `duplicate profile ${name}`);
			claimed.add(name);
			if (profile.overlay) {
				assert.equal(existsSync(join(source.dir, profile.overlay)), true, profile.overlay);
			}
		}
	}
	assert.deepEqual([...claimed].sort(), [...HARNESS_NAMES].sort());
});

test("family shared overlays prepend their profile extras", () => {
	const grok = overlayBody("grok-build");
	assert.match(grok, /Match the user's intent/);
	assert.doesNotMatch(grok, /\n\n/);
	assert.match(overlayBody("grok-build"), /ask_user_question/);
	assert.match(overlayBody("grok-build-plan"), /Plan mode until the harness changes/);
	assert.match(overlayBody("grok-build-plan"), /not perform it/);
	assert.doesNotMatch(overlayBody("grok-build-plan"), /then implement/);

	const codex = overlayBody("codex");
	assert.match(codex, /sharing the user's workspace/);
	assert.match(codex, /Default collaboration mode/);
	assert.match(codex, /Follow the Clarity precheck in AGENTS.md/);
	assert.match(codex, /Cancellation or missing answers are not consent/);
	assert.match(codex, /Use plain-text questions only when ask_user_question is unavailable/);
	for (const name of ["codex", "grok-build", "zcode", "qwen-code"] as const) {
		const body = overlayBody(name);
		assert.match(body, /load clarify-request only when its conditional loading gate is met/);
		assert.match(body, /dependent follow-ups/);
		assert.doesNotMatch(body, /Ask once|only for optional questions|continue with best judgment/);
	}
	assert.match(overlayBody("codex-plan"), /sharing the user's workspace/);
	assert.match(overlayBody("codex-plan"), /Plan mode until the harness changes/);
	assert.match(overlayBody("codex-plan"), /decision-complete/);

	const zcode = overlayBody("zcode");
	assert.match(zcode, /long-horizon/);
	assert.match(zcode, /ask_user_question/);
	assert.match(zcode, /path:line/);
	assert.match(zcode, /Do not retry the same call verbatim/);
	assert.match(overlayBody("zcode-plan"), /Plan mode until the harness changes/);
	assert.match(overlayBody("zcode-plan"), /not perform it/);
	assert.match(overlayBody("zcode-plan"), /genuine fork/);
	assert.doesNotMatch(overlayBody("zcode-plan"), /then implement/);

	const qwen = overlayBody("qwen-code");
	assert.match(qwen, /Do not revert or overwrite unrelated user work/);
	assert.match(qwen, /ask_user_question/);
	assert.match(qwen, /path:line/);
	assert.match(qwen, /Do not retry the same call verbatim/);
	assert.doesNotMatch(qwen, /\n\n/);
	assert.match(overlayBody("qwen-code-plan"), /Plan mode until the harness changes/);
	assert.match(overlayBody("qwen-code-plan"), /not perform it/);
	assert.match(overlayBody("qwen-code-plan"), /what existing code to reuse/);
	assert.doesNotMatch(overlayBody("qwen-code-plan"), /exit_plan_mode/);
	assert.doesNotMatch(overlayBody("qwen-code-plan"), /then implement/);

	const deepseek = overlayBody("deepseek-standard");
	assert.match(deepseek, /Ground work in the repository/);
	assert.doesNotMatch(deepseek, /You are a coding agent/);
	assert.doesNotMatch(deepseek, /\bgrep\b/);
	assert.match(deepseek, /lsp_navigation/);
	assert.match(deepseek, /external, untrusted data/);
	assert.match(overlayBody("deepseek-plan"), /Plan mode until the harness changes/);
	assert.match(overlayBody("deepseek-plan"), /decision-complete/);
	assert.doesNotMatch(overlayBody("deepseek-plan"), /exit_plan_mode/);
	assert.match(overlayBody("deepseek-minimal"), /deliberately small tool surface/);
});

test("renderOverlay wraps the body in a harness tag", () => {
	const rendered = renderOverlay({ name: "grok-build", source: "session" });
	assert.equal(rendered.startsWith("<harness>"), true);
	assert.equal(rendered.endsWith("</harness>"), true);
	assert.doesNotMatch(rendered, /name=|model=|thinking=/);
	assert.ok(rendered.includes(overlayBody("grok-build")));
});

test("default sources root sits next to prompt.ts", () => {
	assert.equal(defaultSourcesRoot().endsWith("/extensions/easy-harness/sources"), true);
});

test("the common layer follows every non-plan overlay and skips plan modes", () => {
	const common = commonBody();
	assert.match(common, /Think concisely/);
	assert.ok(overlayBody("deepseek-minimal").endsWith(common));
	assert.ok(overlayBody("grok-build").endsWith(common));
	for (const plan of ["deepseek-plan", "codex-plan", "grok-build-plan", "zcode-plan", "qwen-code-plan"] as const) {
		assert.doesNotMatch(overlayBody(plan), /Think concisely/);
	}
	assert.doesNotMatch(overlayBody("deepseek-minimal", undefined, false), /Think concisely/);
	assert.ok(renderOverlay({ name: "codex", source: "session" }).includes(common));
});

import assert from "node:assert/strict";
import test from "node:test";
import {
	composeChildPrompt,
	modelRefFromSpec,
	routePromptFamilyForModel,
} from "./prompt-family.ts";
import { parseModelRef } from "./resolve.ts";

test("routes GPT to codex and Grok to grok-build without usage counts", () => {
	assert.equal(routePromptFamilyForModel({ provider: "openai-codex", id: "gpt-5.6-luna" }), "codex");
	assert.equal(routePromptFamilyForModel({ provider: "openai", id: "gpt-5.4" }), "codex");
	assert.equal(routePromptFamilyForModel({ provider: "openrouter", id: "openai/gpt-5.4" }), "codex");
	assert.equal(routePromptFamilyForModel({ provider: "xai", id: "grok-4.6" }), "grok-build");
	assert.equal(routePromptFamilyForModel({ provider: "openrouter", id: "x-ai/grok-4.1-fast" }), "grok-build");
	assert.equal(routePromptFamilyForModel({ provider: "commandcode", id: "z-ai/glm-5.3-flash" }), "zcode");
	assert.equal(routePromptFamilyForModel({ provider: "z-ai", id: "glm-5.3" }), "zcode");
	assert.equal(routePromptFamilyForModel({ provider: "commandcode", id: "Qwen/Qwen3.7-Flash" }), "qwen-code");
	assert.equal(routePromptFamilyForModel({ provider: "openrouter", id: "qwen/qwen3-coder" }), "qwen-code");
	assert.equal(routePromptFamilyForModel({ provider: "deepseek", id: "deepseek-chat" }), "deepseek");
	assert.equal(routePromptFamilyForModel({ provider: "openrouter", id: "deepseek/deepseek-r1" }), "deepseek");
});

test("unknown models and missing models use pi-default", () => {
	assert.equal(routePromptFamilyForModel(undefined), "pi-default");
	assert.equal(routePromptFamilyForModel({ provider: "commandcode", id: "poolside/laguna-s-2.1-free" }), "pi-default");
	assert.equal(routePromptFamilyForModel({ provider: "google", id: "gemini-3.1-pro" }), "pi-default");
});

test("named family and user routes beat built-ins", () => {
	assert.equal(
		routePromptFamilyForModel(
			{ provider: "xai", id: "grok-4.6" },
			{ named: "codex" },
		),
		"codex",
	);
	assert.equal(
		routePromptFamilyForModel(
			{ provider: "commandcode", id: "poolside/laguna-s-2.1-free" },
			{ routes: [{ match: ["commandcode/poolside/laguna-*"], family: "codex" }] },
		),
		"codex",
	);
});

test("compose prepends family shared unless the role prompt already includes it", () => {
	const grok = composeChildPrompt({ family: "grok-build", rolePrompt: "Read-only search." });
	assert.equal(grok.family, "grok-build");
	assert.match(grok.text, /Match the user's intent/);
	assert.match(grok.text, /Read-only search/);
	assert.deepEqual(grok.files, ["grok-build/shared.md", "role"]);

	const baked = composeChildPrompt({
		family: "grok-build",
		rolePrompt: grok.text,
	});
	assert.equal(baked.text, grok.text);

	const legacy = composeChildPrompt({
		family: "codex",
		rolePrompt: "Stay a worker.",
		includesFamilyShared: true,
	});
	assert.equal(legacy.text, "Stay a worker.");
	assert.deepEqual(legacy.files, ["role"]);

	const deepseek = composeChildPrompt({ family: "deepseek", rolePrompt: "Stay a worker." });
	assert.match(deepseek.text, /Ground work in the repository/);
	assert.deepEqual(deepseek.files, ["deepseek/shared.md", "role"]);

	const unknown = composeChildPrompt({ family: "pi-default", rolePrompt: "Stay a worker." });
	assert.equal(unknown.text, "Stay a worker.");
	assert.doesNotMatch(unknown.text, /sharing the user's workspace/);
});

test("model specs parse provider/id for family routing", () => {
	assert.deepEqual(modelRefFromSpec("commandcode/poolside/laguna-s-2.1-free"), {
		provider: "commandcode",
		id: "poolside/laguna-s-2.1-free",
	});
	assert.deepEqual(parseModelRef("openai-codex/gpt-5.6-luna"), {
		provider: "openai-codex",
		id: "gpt-5.6-luna",
	});
});

test("compose appends the common layer only when asked, once", () => {
	const on = composeChildPrompt({ family: "deepseek", rolePrompt: "Stay a worker.", common: true });
	assert.match(on.text, /Ground work in the repository[\s\S]*Stay a worker\.[\s\S]*Think concisely/);
	assert.deepEqual(on.files, ["deepseek/shared.md", "role", "common.md"]);
	assert.equal(composeChildPrompt({ family: "deepseek", rolePrompt: on.text, common: true }).text, on.text);
	assert.doesNotMatch(composeChildPrompt({ family: "deepseek", rolePrompt: "Stay a worker." }).text, /Think concisely/);
	assert.equal(composeChildPrompt({ family: "pi-default", rolePrompt: "Stay a worker.", common: true }).text, "Stay a worker.");
});

import { existsSync, readdirSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import type { HarnessName, ResolvedHarness } from "./types.ts";

export interface UpstreamMap {
	path: string;
	symbol?: string;
	sections?: string[];
	note?: string;
}

export interface ProfileSource {
	overlay?: string | null;
	upstream: UpstreamMap[];
}

export interface HarnessSource {
	family: string;
	ref: {
		path: string;
		remote?: string;
		rev: string;
	};
	watch?: string[];
	shared?: string | null;
	profiles: Record<string, ProfileSource>;
	dir: string;
}

let cached: HarnessSource[] | undefined;

export function defaultSourcesRoot(): string {
	return join(dirname(fileURLToPath(import.meta.url)), "sources");
}

export function loadHarnessSources(root = defaultSourcesRoot()): HarnessSource[] {
	if (!existsSync(root)) return [];
	const out: HarnessSource[] = [];
	for (const name of readdirSync(root)) {
		const dir = join(root, name);
		const file = join(dir, "SOURCE.json");
		if (!existsSync(file)) continue;
		const parsed = JSON.parse(readFileSync(file, "utf8")) as Omit<HarnessSource, "dir">;
		out.push({ ...parsed, dir });
	}
	return out;
}

function sources(root?: string): HarnessSource[] {
	if (root) return loadHarnessSources(root);
	cached ??= loadHarnessSources();
	return cached;
}

function readOptional(dir: string, rel: string | null | undefined): string {
	if (!rel) return "";
	const path = join(dir, rel);
	if (!existsSync(path)) {
		throw new Error(`Missing overlay file: ${path}`);
	}
	return readFileSync(path, "utf8").trim();
}

export function familySharedBody(family: string, root?: string): string {
	for (const source of sources(root)) {
		if (source.family !== family) continue;
		return readOptional(source.dir, source.shared);
	}
	return "";
}

export function overlayBody(name: HarnessName, root?: string): string {
	for (const source of sources(root)) {
		const profile = source.profiles[name];
		if (!profile) continue;
		const parts = [readOptional(source.dir, source.shared), readOptional(source.dir, profile.overlay)];
		return parts.filter(Boolean).join("\n");
	}
	throw new Error(`No overlay source for harness ${name}`);
}

export function renderOverlay(resolved: ResolvedHarness, root?: string): string {
	return `<harness>
${overlayBody(resolved.name, root)}
</harness>`;
}

import { familySharedBody } from "./prompt.ts";
import { parseModelRef } from "./resolve.ts";
import { matchesModel } from "./routing.ts";
import type { HarnessRouteModel } from "./routing.ts";

export type PromptFamily = "codex" | "grok-build" | "zcode" | "qwen-code" | "deepseek" | "pi-default";

export interface PromptFamilyRoute {
	match: readonly string[];
	family: PromptFamily;
}

export interface PromptFamilyConfig {
	named?: PromptFamily;
	routes?: readonly PromptFamilyRoute[];
}

export const DEFAULT_PROMPT_FAMILY_ROUTES = [
	{
		match: ["openai/*", "openai-codex/*", "*/openai/*", "*/openai-codex/*", "gpt-*"],
		family: "codex",
	},
	{
		match: ["xai/*", "x-ai/*", "*/xai/*", "*/x-ai/*", "grok-*"],
		family: "grok-build",
	},
	{
		match: ["z-ai/*", "zai/*", "*/z-ai/*", "*/zai/*", "glm-*"],
		family: "zcode",
	},
	{
		match: ["qwen/*", "alibaba/*", "dashscope/*", "*/qwen/*", "*/alibaba/*", "qwen*", "qwq-*"],
		family: "qwen-code",
	},
	{
		match: ["deepseek/*", "deepseek-ai/*", "*/deepseek/*", "*/deepseek-ai/*", "deepseek-*"],
		family: "deepseek",
	},
] as const satisfies readonly PromptFamilyRoute[];

export function parsePromptFamily(value: unknown): PromptFamily | undefined {
	return value === "codex" || value === "grok-build" || value === "zcode" || value === "qwen-code"
		|| value === "deepseek" || value === "pi-default"
		? value
		: undefined;
}

export function modelRefFromSpec(spec: string | undefined): HarnessRouteModel | undefined {
	if (!spec?.trim()) return undefined;
	return parseModelRef(spec.trim());
}

/** Child prompt family from the resolved model. Does not use parent usage or DEFAULT_HARNESS. */
export function routePromptFamilyForModel(
	model: HarnessRouteModel | undefined,
	config: PromptFamilyConfig = {},
): PromptFamily {
	if (config.named) return config.named;
	if (!model) return "pi-default";
	for (const route of [...(config.routes ?? []), ...DEFAULT_PROMPT_FAMILY_ROUTES]) {
		if (route.match.some((pattern) => matchesModel(pattern, model))) return route.family;
	}
	return "pi-default";
}

export function composeChildPrompt(input: {
	family: PromptFamily;
	rolePrompt: string;
	includesFamilyShared?: boolean;
	root?: string;
}): { family: PromptFamily; text: string; files: string[] } {
	const rolePrompt = input.rolePrompt.trim();
	if (input.includesFamilyShared || input.family === "pi-default") {
		return {
			family: input.family,
			text: rolePrompt,
			files: rolePrompt ? ["role"] : [],
		};
	}
	const shared = familySharedBody(input.family, input.root).trim();
	if (!shared) {
		return {
			family: input.family,
			text: rolePrompt,
			files: rolePrompt ? ["role"] : [],
		};
	}
	if (rolePrompt.includes(shared)) {
		return {
			family: input.family,
			text: rolePrompt,
			files: [`${input.family}/shared.md`, "role"],
		};
	}
	const text = [shared, rolePrompt].filter(Boolean).join("\n");
	return {
		family: input.family,
		text,
		files: rolePrompt ? [`${input.family}/shared.md`, "role"] : [`${input.family}/shared.md`],
	};
}

