edits.oldText:
export function composeChildPrompt(input: {
	family: PromptFamily;
	rolePrompt: string;
	includesFamilyShared?: boolean;
	root?: string;
}): { family: PromptFamily; text: string; files: string[] } {
	const rolePrompt = input.rolePrompt.trim();
	if (input.includesFamilyShared || input.family === "pi-default") {
		return {
			family: input.family,
			text: rolePrompt,
			files: rolePrompt ? ["role"] : [],
		};
	}
	const shared = familySharedBody(input.family, input.root).trim();
	if (!shared) {
		return {
			family: input.family,
			text: rolePrompt,
			files: rolePrompt ? ["role"] : [],
		};
	}
	if (rolePrompt.includes(shared)) {
		return {
			family: input.family,
			text: rolePrompt,
			files: [`${input.family}/shared.md`, "role"],
		};
	}
	const text = [shared, rolePrompt].filter(Boolean).join("\n");
	return {
		family: input.family,
		text,
		files: rolePrompt ? [`${input.family}/shared.md`, "role"] : [`${input.family}/shared.md`],
	};
}

edits.newText:
export function composeChildPrompt(input: {
	family: PromptFamily;
	rolePrompt: string;
	includesFamilyShared?: boolean;
	common?: boolean;
	root?: string;
}): { family: PromptFamily; text: string; files: string[] } {
	const rolePrompt = input.rolePrompt.trim();
	if (input.family === "pi-default") {
		return {
			family: input.family,
			text: rolePrompt,
			files: rolePrompt ? ["role"] : [],
		};
	}
	const files: string[] = [];
	let text = rolePrompt;
	let hasShared = false;
	if (!input.includesFamilyShared) {
		const shared = familySharedBody(input.family, input.root).trim();
		if (shared) {
			hasShared = true;
			files.push(`${input.family}/shared.md`);
			if (!rolePrompt.includes(shared)) {
				text = [shared, rolePrompt].filter(Boolean).join("\n");
			}
		}
	}
	if (rolePrompt) {
		files.push("role");
	}
	if (input.common) {
		const common = commonBody(input.root).trim();
		if (common) {
			if (!text.includes(common)) {
				text = text ? `${text}\n${common}` : common;
			}
			files.push("common.md");
		}
	}
	void hasShared;
	return { family: input.family, text, files };
}

